const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.inList('ADM0_NAME', ['Namibia', 'Botswana', 'Lesotho']));
  const geometry = countries.geometry();

  const targetStartDate = '2018-12-01';
  const targetEndDate = '2019-01-31';

  const longTermStartYear = 2000;
  const longTermEndYear = 2019; // The period is 2000-2019, so the last season is Dec 2018 - Jan 2019

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Check if data is available for the first year to avoid running the whole script
  const initialCheck = chirps.filterDate('2000-12-01', '2001-01-31').size().getInfo();
  if (initialCheck === 0) {
      console.log('No data found for the start of the long-term period.');
      console.log('C1');
      return;
  }

  // 3. Processing: Calculate Target Period Rainfall
  const targetCollection = chirps.filterDate(targetStartDate, targetEndDate);
  if (targetCollection.size().getInfo() === 0) {
    console.log(`No images found for the target period: ${targetStartDate} to ${targetEndDate}.`);
    console.log('C1');
    return;
  }
  const targetTotalPrecip = targetCollection.sum().clip(geometry);

  const scale = 5000;
  const targetMean = targetTotalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e10
  }).get('precipitation');

  const targetMeanValue = targetMean.getInfo();

  // 4. Processing: Calculate Long-Term Average Rainfall
  const years = ee.List.sequence(longTermStartYear, longTermEndYear - 1);

  const seasonalTotals = ee.ImageCollection.fromImages(
    years.map(function(y) {
      const year = ee.Number(y);
      const start = ee.Date.fromYMD(year, 12, 1);
      const end = ee.Date.fromYMD(year.add(1), 1, 31);
      const seasonalCollection = chirps.filterDate(start, end);
      const total = seasonalCollection.sum().clip(geometry);
      return total.set('year', y);
    })
  );

  // Check if collection was created successfully
  if (seasonalTotals.size().getInfo() === 0) {
      console.log('Failed to create long-term seasonal collection.');
      console.log('C1');
      return;
  }

  const longTermMeanPrecip = seasonalTotals.mean();
  const longTermMean = longTermMeanPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e10
  }).get('precipitation');

  const longTermMeanValue = longTermMean.getInfo();

  // 5. Validation & Final Answer
  if (targetMeanValue === null || longTermMeanValue === null) {
      console.log('Calculation resulted in null.');
      console.log(`Target Period Mean: ${targetMeanValue}`);
      console.log(`Long-Term Mean: ${longTermMeanValue}`);
      console.log('C3');
      return;
  }

  const countReducer = ee.Reducer.count();
  const targetPixelCount = targetTotalPrecip.reduceRegion({
      reducer: countReducer, geometry: geometry, scale: scale, maxPixels: 1e10
  }).get('precipitation').getInfo();

  if (targetPixelCount === 0) {
      console.log('No valid pixels found in the region of interest for the target period.');
      console.log('C2');
      return;
  }

  console.log(`Region: Namibia, Botswana, Lesotho`);
  console.log(`Target Period (Dec 2018 - Jan 2019) Total Rainfall: ${targetMeanValue.toFixed(2)} mm`);
  console.log(`Long-Term Avg (Dec-Jan, 2000-2019) Total Rainfall: ${longTermMeanValue.toFixed(2)} mm`);
  console.log(`Valid Pixel Count: ${targetPixelCount}`);

  if (targetMeanValue < longTermMeanValue) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
